$_MODULE['<{sudemi}prestashop>sudemi_2ed47a037d74feebec0f061fec1fb103'] = 'Anuluje zamówienie i zwraca kupującemu całą kwotę. Tylko przed wysyłką.';
$_MODULE['<{sudemi}prestashop>sudemi_f5b09d3a51a5e37eba3c7dac46e5df1b'] = 'Zaakceptowano. Kupujący został obciążony; wyślij zamówienie.';
$_MODULE['<{sudemi}prestashop>sudemi_98952b0b90aa4fb194096fe192fdbc21'] = 'Zaakceptowano. Kupujący zapłacił kilku sklepom naraz: sudemi pobiera pieniądze, gdy odpowie każdy sklep. Nie wysyłaj, zanim zamówienie nie będzie Potwierdzone i obciążone.';
$_MODULE['<{sudemi}prestashop>sudemi_dcb1f24d0d95eba6033b7e1290de67ab'] = 'Odrzucono. Kupujący nie został obciążony.';
$_MODULE['<{sudemi}prestashop>sudemi_6d038398f806b60fd184e59efafdcb3b'] = 'sudemi ma teraz zamówienie jako wysłane i informuje kupującego.';
$_MODULE['<{sudemi}prestashop>sudemi_6d34245515db681deda225bb8edf1710'] = 'sudemi ma teraz zamówienie jako doręczone. Termin zwrotu dla kupującego biegnie od dziś.';
