$_MODULE['<{sudemi}prestashop>sudemi_78784fa63f22766c603bbfa698038653'] = 'Twoja odpowiedź została wysłana do sudemi.';
$_MODULE['<{sudemi}prestashop>sudemi_4f57f58233621c572257df4751e231e3'] = 'Numer przesyłki wysłano do sudemi; sudemi poinformuje kupującego.';
$_MODULE['<{sudemi}prestashop>sudemi_fc80874c6371bd86fe3fab5294e5c4b1'] = 'sudemi ma już nowszy stan tego zamówienia. Nic nie zmieniono; strona pokazuje teraz stan w sudemi.';
$_MODULE['<{sudemi}prestashop>sudemi_c67e2255c45d13d55319a11a608ae1ff'] = 'Nie zaakceptowano, nic nie wysłano: %s. Odrzuć zamówienie albo udostępnij produkt i zaakceptuj ponownie.';
$_MODULE['<{sudemi}prestashop>sudemi_e0786cf9f182c4f26c994bba5f2a80ff'] = 'Podaj kwotę większą od zera i nie wyższą niż to, co można jeszcze zwrócić.';
